'use strict';

const logger = require('@yandex-int/yandex-logger')({
    name: 'yandex-logger',
    streams: [
        {
            level: 'info',
            stream: require('@yandex-int/yandex-logger/streams/json')({ stream: process.stdout }),
        },
        {
            level: 'error',
            stream: require('@yandex-int/yandex-logger/streams/json')({ stream: process.stderr }),
        },
    ],
});

// 1. Простое сообщение
logger.info('Log message');

// 2. Логируем только ошибку
let err = new Error('Something went wrong!');
logger.error(err);

// 3. Логируем сложный объект
let entry = require('./entry');
logger.error(entry);
